  BEGIN app_req   := NULLIF(btrim(current_setting('app.request_id', true)), ''); EXCEPTION WHEN OTHERS THEN app_req   := NULL; END;

  IF TG_OP = 'UPDATE' THEN
    FOR r IN
      SELECT a.attname AS col
      FROM pg_attribute a
      WHERE a.attrelid = TG_RELID
        AND a.attnum > 0
        AND NOT a.attisdropped
      ORDER BY a.attnum
    LOOP
      IF r.col = ANY (ign) THEN CONTINUE; END IF;

      EXECUTE format('SELECT ($1).%I::text, ($2).%I::text', r.col, r.col)
      USING OLD, NEW INTO o_txt, n_txt;

      IF o_txt IS DISTINCT FROM n_txt THEN
        diff := diff || jsonb_build_object(
          r.col,
          jsonb_build_object('old', to_jsonb(o_txt), 'new', to_jsonb(n_txt))
        );
      END IF;
    END LOOP;

    IF diff = '{}'::jsonb THEN RETURN NEW; END IF;
    tuple_source := 'diff';
    dados_json := diff;
  ELSIF TG_OP = 'INSERT' THEN
    tuple_source := 'new';
    dados_json := row_to_json(NEW)::jsonb;
  ELSE
    tuple_source := 'old';
    dados_json := row_to_json(OLD)::jsonb;
